/* Coffeetableviz EPL 2025-26 — deterministic interactive SVG; data generated by archived Python script. */
(function () {
  'use strict';
  const root = document.getElementById('epl-unfolded');
  if (!root || root.dataset.loaded === '1') return;
  root.dataset.loaded = '1';
  const svg = root.querySelector('#eplu-svg');
  const plot = root.querySelector('#eplu-plot');
  const tip = root.querySelector('#eplu-tooltip');
  const clubSelect = root.querySelector('#eplu-team');
  const compareSelect = root.querySelector('#eplu-compare');
  const slider = root.querySelector('#eplu-match');
  const matchLabel = root.querySelector('#eplu-match-label');
  const status = root.querySelector('#eplu-status');
  const clear = root.querySelector('#eplu-clear');
  const table = root.querySelector('#eplu-table-body');
  const ns = 'http://www.w3.org/2000/svg';
  const colours = { focus: '#1F8FA8', compare: '#C44E52', context: '#929AA3' };
  const number = n => Number(n).toLocaleString('en-GB');

  let season = null;
  let selected = 'Arsenal';
  let compare = 'Man City';
  let matchNumber = 38;
  let widthPreviously = 0;
  let xScale = null;
  let yScale = null;
  let activePreview = null;

  function make(tag, cls, value) {
    const el = document.createElement(tag);
    if (cls) el.className = cls;
    if (value !== undefined) el.textContent = value;
    return el;
  }
  function node(parent, tag, attrs, value) {
    const el = document.createElementNS(ns, tag);
    Object.entries(attrs || {}).forEach(([key, val]) => el.setAttribute(key, String(val)));
    if (value !== undefined) el.textContent = String(value);
    parent.appendChild(el);
    return el;
  }
  function teamByName(name) {
    return season && season.teams.find(team => team.name === name);
  }
  function pointsAt(team, numberPlayed) {
    return numberPlayed === 0 ? 0 : team.games[numberPlayed - 1].points;
  }
  function resetTooltip() {
    activePreview = null;
    if (selected) showTooltip(teamByName(selected), matchNumber, true);
    else tip.hidden = true;
  }
  function showTooltip(team, match, pinned) {
    if (!team || match < 1 || match > 38 || !xScale || !yScale) return;
    const game = team.games[match - 1];
    tip.replaceChildren();
    const top = make('div', 'eplu-tip-overline');
    const clubTag = make('span', '', pinned ? '● SELECTED' : 'MATCH PREVIEW');
    clubTag.style.color = pinned ? colours.focus : '#56626C';
    top.appendChild(clubTag);
    top.appendChild(make('span', '', 'MATCH ' + match + ' / 38'));
    tip.appendChild(top);
    tip.appendChild(make('div', 'eplu-tip-team', team.name));
    tip.appendChild(make('div', 'eplu-tip-line', 'Final position: ' + team.rank + ' of 20'));
    const metrics = make('div', 'eplu-tip-metrics');
    for (const item of [['POINTS SO FAR', String(game.points)], ['RESULT', game.result]]) {
      const col = make('div');
      col.appendChild(make('small', '', item[0]));
      col.appendChild(make('strong', '', item[1]));
      metrics.appendChild(col);
    }
    tip.appendChild(metrics);
    const homeScore = game.venue === 'H' ? game.gf : game.ga;
    const awayScore = game.venue === 'H' ? game.ga : game.gf;
    const home = game.venue === 'H' ? team.name : game.opponent;
    const away = game.venue === 'H' ? game.opponent : team.name;
    const date = new Date(game.date + 'T12:00:00Z').toLocaleDateString('en-GB', {day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
    tip.appendChild(make('div', 'eplu-tip-foot', date + ' · ' + home + ' ' + homeScore + '–' + awayScore + ' ' + away));
    tip.hidden = false;

    const plotWidth = plot.clientWidth;
    const plotHeight = svg.getBoundingClientRect().height;
    const px = xScale(match);
    const py = yScale(game.points);
    const tipWidth = tip.offsetWidth, tipHeight = tip.offsetHeight, edge = 4;
    let left = px + 13;
    if (left + tipWidth > plotWidth - edge) left = px - tipWidth - 13;
    left = Math.max(edge, Math.min(Math.max(edge, plotWidth - tipWidth - edge), left));
    let topPx = py - tipHeight - 12;
    if (topPx < edge) topPx = py + 13;
    topPx = Math.max(edge, Math.min(Math.max(edge, plotHeight - tipHeight - edge), topPx));
    tip.style.left = left + 'px';
    tip.style.top = topPx + 'px';
  }
  function updateControls() {
    clubSelect.value = selected || '';
    compareSelect.value = compare || '';
    clear.disabled = !selected;
    slider.value = String(matchNumber);
    matchLabel.textContent = String(matchNumber);
    status.textContent = selected
      ? selected + ' · ' + pointsAt(teamByName(selected), matchNumber) + ' points after ' + matchNumber + ' matches'
      : 'All 20 clubs · select a line or a club';
    table.querySelectorAll('tr[data-team]').forEach(row => {
      row.setAttribute('aria-selected', String(!!selected && row.dataset.team === selected));
    });
  }
  function choose(name) {
    selected = name && name === selected ? null : name;
    if (selected === compare) compare = null;
    activePreview = null;
    update();
  }
  function update() {
    updateControls();
    drawChart();
  }
  function pathFor(team, xp, yp) {
    let d = 'M' + xp(0).toFixed(2) + ',' + yp(0).toFixed(2);
    team.games.forEach(game => {
      d += 'L' + xp(game.number).toFixed(2) + ',' + yp(game.points).toFixed(2);
    });
    return d;
  }
  function drawChart() {
    if (!season) return;
    const W = Math.max(260, Math.round(plot.clientWidth || 360));
    widthPreviously = W;
    const small = W < 600;
    const H = small ? Math.max(330, Math.min(382, W * 1.06)) : 475;
    const L = small ? 43 : 62, R = small ? 14 : 24;
    const T = 20, B = small ? 45 : 51;
    const plotW = W - L - R, plotH = H - T - B;
    const xp = game => L + (game / 38) * plotW;
    const yp = points => T + plotH - (points / 90) * plotH;
    xScale = xp; yScale = yp;
    svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
    svg.replaceChildren();
    tip.hidden = true;
    node(svg, 'rect', { x:0,y:0,width:W,height:H,fill:'transparent' });
    [0,20,40,60,80,90].forEach(points => {
      const y = yp(points);
      node(svg,'line',{x1:L,x2:W-R,y1:y,y2:y,stroke:'#D5DDE1','stroke-width':1});
      node(svg,'text',{x:L-9,y:y+4,'text-anchor':'end',fill:'#62727D','font-size':small?10:12,'font-family':'IBM Plex Mono, monospace'},points);
    });
    [0,10,20,30,38].forEach(game => {
      const x=xp(game);
      node(svg,'line',{x1:x,x2:x,y1:T,y2:T+plotH,stroke:'#E0E5E8','stroke-width':1});
      node(svg,'text',{x:x,y:H-B+19,'text-anchor':'middle',fill:'#62727D','font-size':small?10:12,'font-family':'IBM Plex Mono, monospace'},game);
    });
    node(svg,'text',{x:L+plotW/2,y:H-5,'text-anchor':'middle',fill:'#53636E','font-size':small?11:13},'Club match number (not calendar week)');
    node(svg,'text',{x:11,y:T+plotH/2,transform:'rotate(-90 11 '+(T+plotH/2)+')','text-anchor':'middle',fill:'#53636E','font-size':small?10:13},'Cumulative points');
    const ordered = [...season.teams].reverse();
    if (compare && compare !== selected) {
      const index = ordered.findIndex(t => t.name === compare);
      if (index >= 0) ordered.push(ordered.splice(index,1)[0]);
    }
    if (selected) {
      const index = ordered.findIndex(t => t.name === selected);
      if (index >= 0) ordered.push(ordered.splice(index,1)[0]);
    }
    ordered.forEach(team => {
      const focus = selected === team.name;
      const secondary = !!selected && compare === team.name && !focus;
      const ink = focus ? colours.focus : secondary ? colours.compare : colours.context;
      const opacity = selected && !focus && !secondary ? 0.43 : 1;
      const d = pathFor(team, xp, yp);
      node(svg,'path',{d,fill:'none',stroke:ink,'stroke-width':focus?3.5:secondary?2.6:1.45,'stroke-linejoin':'round','stroke-linecap':'round',opacity});
    });
    if (selected) {
      const guideX = xp(matchNumber);
      node(svg,'line',{x1:guideX,y1:T,x2:guideX,y2:T+plotH,stroke:colours.focus,'stroke-width':1,'stroke-dasharray':'4 5',opacity:.65});
    }
    ordered.forEach(team => {
      const d=pathFor(team,xp,yp);
      const hit=node(svg,'path',{d,fill:'none',stroke:'transparent','stroke-width':small?16:13,'stroke-linejoin':'round','stroke-linecap':'round','pointer-events':'stroke','data-team':team.name,tabindex:0,role:'button','aria-label':'Select '+team.name+' season points line',style:'cursor:pointer'});
      hit.addEventListener('click',event=>{event.stopPropagation();choose(team.name)});
      hit.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();event.stopPropagation();choose(team.name)}});
      hit.addEventListener('pointermove',event=>{
        if(event.pointerType==='touch')return;
        const rect=svg.getBoundingClientRect();
        const localX=(event.clientX-rect.left)*W/rect.width;
        const step=Math.max(1,Math.min(38,Math.round((localX-L)/plotW*38)));
        if(activePreview && activePreview.team===team.name && activePreview.match===step)return;
        activePreview={team:team.name,match:step};
        showTooltip(team,step,false);
      });
      hit.addEventListener('pointerleave',()=>resetTooltip());
      hit.addEventListener('focus',()=>showTooltip(team,matchNumber,false));
      hit.addEventListener('blur',()=>resetTooltip());
    });
    if (compare && compare !== selected && selected) {
      const club=teamByName(compare),v=pointsAt(club,matchNumber);
      node(svg,'circle',{cx:xp(matchNumber),cy:yp(v),r:5,fill:colours.compare,stroke:'#F3F4F6','stroke-width':1});
    }
    if (selected) {
      const team=teamByName(selected),points=pointsAt(team,matchNumber);
      node(svg,'circle',{cx:xp(matchNumber),cy:yp(points),r:9.5,fill:'none',stroke:'#25323C','stroke-width':1.6,'pointer-events':'none'});
      node(svg,'circle',{cx:xp(matchNumber),cy:yp(points),r:6.2,fill:colours.focus,stroke:'#F3F4F6','stroke-width':1.2,'pointer-events':'none'});
    }
    if (selected) showTooltip(teamByName(selected),matchNumber,true);
  }
  function buildOptions() {
    const teamOptions=season.teams.map(t=>({value:t.name,label:t.name+' · '+t.points+' pts'}));
    teamOptions.forEach(o=>{
      const opt=make('option','',o.label);opt.value=o.value;clubSelect.appendChild(opt);
      const comp=make('option','',o.label);comp.value=o.value;compareSelect.appendChild(comp);
    });
    clubSelect.value=selected;
    compareSelect.value=compare;
  }
  function buildTable() {
    table.replaceChildren();
    season.teams.forEach(team=>{
      const row=make('tr');row.dataset.team=team.name;
      const rank=make('td','',String(team.rank));
      const club=make('td');
      const button=make('button','',team.name);
      button.type='button';
      button.addEventListener('click',()=>{choose(team.name);plot.scrollIntoView({behavior:'smooth',block:'nearest'})});
      club.appendChild(button);
      row.append(rank,club,make('td','',String(team.points)),make('td','',(team.gd>0?'+':'')+String(team.gd)));
      table.appendChild(row);
    });
  }
  function load() {
    fetch(root.dataset.source, {cache:'force-cache'})
      .then(response=>{if(!response.ok)throw new Error('HTTP '+response.status);return response.json()})
      .then(json=>{
        if(!json || json.meta.matchCount!==380 || !Array.isArray(json.teams) || json.teams.length!==20 || json.teams.some(t=>t.games.length!==38)) throw new Error('Dataset failed 380-match / 20-team / 38-game QA');
        season=json;
        buildOptions();buildTable();update();
      })
      .catch(error=>{
        status.textContent='Unable to load verified season data. Please refresh this page.';
        table.replaceChildren();
        const tr=make('tr'),td=make('td','',error.message+' · Source data is available via GitHub');td.colSpan=4;tr.appendChild(td);table.appendChild(tr);
      });
  }
  svg.addEventListener('click',event=>{
    if (event.target.closest('[data-team]')) return;
    if (selected) { selected=null; activePreview=null; update(); }
  });
  clear.addEventListener('click',()=>{selected=null;activePreview=null;update()});
  clubSelect.addEventListener('change',()=>{
    selected=clubSelect.value || null;
    if (selected===compare)compare=null;
    activePreview=null;update();
  });
  compareSelect.addEventListener('change',()=>{
    compare=compareSelect.value || null;
    if (compare===selected)compare=null;
    activePreview=null;update();
  });
  slider.addEventListener('input',()=>{
    matchNumber=Number(slider.value);
    activePreview=null;update();
  });
  if (typeof ResizeObserver !== 'undefined') {
    new ResizeObserver(()=>{
      const next=Math.round(plot.clientWidth);
      if(season && next>0 && next!==widthPreviously)drawChart();
    }).observe(plot);
  }
  load();
})();
